fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32> {
    // Create a new vector by concatenating the prefix and suffix
    let mut new_list = Vec::with_capacity(list.len() - 1);
    
    // Add elements before the k-th element (1-based index)
    new_list.extend_from_slice(&list[0..k-1]);
    // Add elements after the k-th element
    new_list.extend_from_slice(&list[k..]);
    
    new_list
}